			$("#transformScaleY").value = Math.round(Math.abs(s.scaleY) * 100);
			$("#transformOpacity").value = Math.round(s.opacity * 100);
			$("#transformOpacityNumber").value = Math.round(s.opacity * 100);
			$("#transformBlend").value = s.blendMode;
			$("#transformLink").classList.toggle("active", transformPrefs.linked);
			$("#transformFlipX").classList.toggle("active", s.scaleX < 0);
			$("#transformFlipY").classList.toggle("active", s.scaleY < 0);
			$("#transformLock").classList.toggle("active", s.locked);
