			const effectiveGravity = s.scope === "sticker" ? !!s.gravityAfterPeel : !!s.gravity;
			$("#transformGravity").classList.toggle("active", effectiveGravity);
			$("#transformGravity").textContent = s.scope === "sticker" ? effectiveGravity ? "After Peel On" : "After Peel Off" : effectiveGravity ? "Gravity On" : "Gravity Off";
			$("#transformPeel").disabled = s.scope !== "sticker";
