		async onFocusChanged(handler) {
			const unlistenFocus = await this.listen(TauriEvent.WINDOW_FOCUS, (event) => {
				handler({
					...event,
					payload: true
				});
			});
			const unlistenBlur = await this.listen(TauriEvent.WINDOW_BLUR, (event) => {
				handler({
					...event,
					payload: false
				});
			});
			return () => {
				unlistenFocus();
				unlistenBlur();
			};
		}
