			frogBrooch.position.set(0, 1.72, .49);
			frogBrooch.scale.set(1.3, .84, .45);
			buddy.add(frogBrooch);
			const orb = new Mesh(new SphereGeometry(.27, 26, 18), this.glassMaterial(13236184, .72));
			orb.position.set(-.65, .86, .24);
			buddy.add(orb);
			const halo = new Mesh(new TorusGeometry(.72, .025, 8, 72), armor);
			halo.position.set(0, 2.38, -.4);
